/** Описание кода ошибки: что значит, насколько серьёзно (0 — можно ездить, 1 — в сервис, 2 — не ехать) и что проверить. */
data class DtcInfo(val code: String, val title: String, val severity: Int, val hint: String)

object Dtc {
    /** 2 байта (4 hex-символа) → код вида P0301. */
    fun decode(hex: String): String {
        val v = hex.toInt(16)
        val sys = "PCBU"[(v shr 14) and 3]
        val d1 = (v shr 12) and 3
        return "$sys$d1" + "%03X".format(v and 0xFFF)
    }

    private fun d(title: String, sev: Int, hint: String) = Triple(title, sev, hint)

