    /** Общие подсказки по диапазону, если конкретного кода нет в справочнике. */
    private fun byRange(code: String): Pair<String, String> {
        val sys = code[0]
        val generic = code[1] == '0' || code[1] == '2'
        val group = code.getOrNull(2)
        val p = when (sys) {
            'P' -> when (group) {
                '0', '1', '2' -> tr("Топливо и воздух (смесь, датчики впуска, форсунки)", "Паливо й повітря (суміш, датчики впуску, форсунки)")
                '3' -> tr("Система зажигания или пропуски зажигания", "Система запалювання або пропуски запалювання")
                '4' -> tr("Системы снижения токсичности (EGR, катализатор, EVAP)", "Системи зниження токсичності (EGR, каталізатор, EVAP)")
                '5' -> tr("Скорость, холостой ход, вспомогательные входы", "Швидкість, холостий хід, допоміжні входи")
                '6' -> tr("Блок управления и его выходные цепи", "Блок керування та його вихідні ланцюги")
                '7', '8', '9' -> tr("Трансмиссия", "Трансмісія")
                'A', 'B', 'C' -> tr("Гибридная силовая установка", "Гібридна силова установка")
                else -> tr("Силовой агрегат", "Силовий агрегат")
            }
            'C' -> tr("Шасси: ABS, ESP, подвеска, рулевое", "Шасі: ABS, ESP, підвіска, рульове")
            'B' -> tr("Кузов: подушки безопасности, комфорт, климат", "Кузов: подушки безпеки, комфорт, клімат")
            else -> tr("Сеть передачи данных между блоками", "Мережа передачі даних між блоками")
        }
        return p to if (generic) tr("Общий (стандартный OBD2) код", "Загальний (стандартний OBD2) код") else tr("Код производителя — расшифровку уточните по марке", "Код виробника — розшифровку уточніть за маркою")
    }

    fun info(code: String): DtcInfo {
        known[code]?.let { (t, s, h) -> return DtcInfo(code, t, s, h) }
        val (group, kind) = byRange(code)
        return DtcInfo(code, group, 1, tr("$kind. Нет в справочнике приложения.", "$kind. Немає в довіднику застосунку."))
    }

    fun severityLabel(s: Int) = when (s) {
        2 -> tr("Серьёзно — лучше не ехать / срочно в сервис", "Серйозно — краще не їхати / терміново в сервіс")
        1 -> tr("Нужна диагностика в ближайшее время", "Потрібна діагностика найближчим часом")
        else -> tr("Можно ездить, устранить при случае", "Можна їздити, усунути за нагоди")
    }
